"""SimMarket: background flow generated by the newtok simulator, B episodes at once.

An episode starts from a real day (history.start_state): the book, the 3,968
real rows the signal reads, and the simulator's context, the last
CONTEXT_MESSAGES - n_messages - AGENT_MARGIN real messages, so that the whole
episode stays within newtok_a_r1's longest training window (4,096 messages).

`advance()` moves every row by one background message:

1. Agent orders that are due become messages and are fed as forced tokens, so
   the simulator sees them. A limit order rests at the back of its queue
   (event 1); a cancel removes the agent's order (event 3); a market order
   takes the opposite side level by level, front of queue first (event 4).
   Each comes 1 ns after the previous message. A limit order that would cross,
   or is not a whole number of cents, is refused, and so is any agent order
   that would leave a side of the book empty (see sampling.empties_side).
2. A background message is drawn whole and kept only if sampling.finish
   accepts it; otherwise the row's cache is cut back to the message start and
   it is drawn again from the cached first-token distribution. After
   MAX_REJECTIONS draws every token is masked to sampling.legal_tokens.
3. The message changes the book; an execution that reaches an agent order is
   the agent's passive (maker) fill. The processed rows and L10 rows go to the
   row log, which the signal reads.

Rows that finish their message wait for the others (lockstep). Random numbers
come from (episode seed, message index, attempt), so two policies on the same
episode see the same background draws until their orders differ.
"""

from __future__ import annotations

from collections import Counter
from dataclasses import dataclass, field

import numpy as np
import torch

from post_training.policy_bench.book import AGENT, ASK, BID, side_of_direction
from post_training.policy_bench.codec import MAX_SIZE, NS, Message, burst_bounds, encode, encode_stream, mid_floor
from post_training.policy_bench.history import open_day, start_state
from post_training.policy_bench.nanosigma.data import START, TICK, book_features
from post_training.policy_bench.rules import LAST_SLOT, slot_candidates
from post_training.policy_bench.sampling import (
    MAX_REJECTIONS, MessageState, file_end_ns, finish, legal_tokens, side_volume,
)
from post_training.policy_bench.signal import price_rel_clip, processed_row
from post_training.policy_bench.simulator import BatchKVSimulator
from post_training.policy_bench.trace import Trace
from post_training.policy_bench.types import BUY, Cancel, Fill, LimitOrder, MarketOrder, Obs, mid_of

CONTEXT_MESSAGES = 4096     # newtok_a_r1's longest training window (phase 4096)
AGENT_MARGIN = 128          # messages kept free for agent orders
MAX_TOKENS_PER_MESSAGE = 17
BG_OID0, AGENT_OID0 = 8 * 10**15, 9 * 10**15


@dataclass
class _Row:
    ep: object
    book: object
    log: object
    reg: object
    writer: object
    clip: int
    end: int
    k: int = 0
    position: int = 0
    cash: float = 0.0
    refused: int = 0
    pending: list = field(default_factory=list)       # (active at k, order)
    resting: dict = field(default_factory=dict)       # agent oid -> side
    fills: list = field(default_factory=list)
    new: list = field(default_factory=list)
    mids: list = field(default_factory=list)
    decisions: list = field(default_factory=list)
    signals: list = field(default_factory=list)
    gen: Counter = field(default_factory=Counter)
    # decoding
    inp: int = START
    bvec: np.ndarray | None = None
    agent: list = field(default_factory=list)         # agent messages waiting: (tokens, bvec after)
    forced: list = field(default_factory=list)        # tokens left of the agent message being fed
    after: np.ndarray | None = None                   # book vector once that message is fed
    state: MessageState | None = None
    attempt: int = 0
    rng: np.random.Generator | None = None
    logits0: np.ndarray | None = None
    n_start: int = 0
    bg_done: bool = True
    next_bg: int = BG_OID0
    next_agent: int = AGENT_OID0


class SimMarket:
    supports = (MarketOrder, LimitOrder, Cancel)

    def __init__(self, model, shard_root: str, add_dir: str, batch: int, history: int = 3968,
                 n_messages: int = 1024, latency: int = 1, inventory_cap: int = 1000,
                 dtype: torch.dtype = torch.bfloat16, max_rejections: int = MAX_REJECTIONS) -> None:
        self.shard_root, self.add_dir, self.batch = shard_root, add_dir, batch
        self.max_rejections = max_rejections
        self.history, self.n_messages, self.latency, self.cap = history, n_messages, latency, inventory_cap
        self.context = CONTEXT_MESSAGES - n_messages - AGENT_MARGIN
        self.sim = BatchKVSimulator(model, batch, CONTEXT_MESSAGES * MAX_TOKENS_PER_MESSAGE + 8192, dtype)
        self.dev = model.embed.weight.device
        self.rows: list[_Row] = []

    # ------------------------------------------------------------ episode
    def reset(self, eps: list) -> None:
        if not 0 < len(eps) <= self.batch:
            raise ValueError(f"{len(eps)} episodes for a batch of {self.batch}")
        self.rows = []
        for i in range(self.batch):
            self.sim.truncate(i, 0)
        for i, ep in enumerate(eps):
            day, index = open_day(self.shard_root, self.add_dir, ep.entry)
            book, log, reg, writer, slots = start_state(day, index, ep.start, self.history,
                                                        8 * self.n_messages + 4 * AGENT_MARGIN)
            r = _Row(ep, book, log, reg, writer, price_rel_clip(ep.entry["message"]),
                     file_end_ns(ep.entry["message"]))
            rows, l10 = log.rows(self.history), log.l10(self.history + 1)
            bounds = burst_bounds(rows)
            r0 = bounds[max(0, len(bounds) - self.context)][0]
            tok, mot, first = encode_stream(rows[r0:], l10[r0:-1], slots[r0:])
            bvec = book_features(l10[r0:-1][first])[mot]
            inp = np.concatenate([[START], tok[:-1]])
            self.sim.prefill(i, torch.as_tensor(inp, device=self.dev), torch.as_tensor(bvec, device=self.dev))
            r.inp, r.bvec = int(tok[-1]), self._bvec(r)
            r.mids.append(mid_of(log.now[3:]))
            r.gen["context_tokens"] = len(tok)
            self.rows.append(r)

    def done(self) -> bool:
        return all(r.k >= self.n_messages for r in self.rows)

    def log(self, i: int):
        return self.rows[i].log

    def observe(self, i: int) -> Obs:
        r = self.rows[i]
        t = r.log.rows(1)[0]
        obs = Obs(r.k, int(t[8]), int(t[9]), r.log.now[3:].copy(), r.position, r.cash,
                  [(oid, side) for oid, side in r.resting.items()], r.new)
        r.new = []
        return obs

    def record_decision(self, i: int, signal) -> None:
        r = self.rows[i]
        r.decisions.append(r.k)
        if signal is not None:
            r.signals.append(np.asarray(signal, np.float64))

    def submit(self, i: int, orders) -> None:
        r = self.rows[i]
        for o in orders:
            if not isinstance(o, self.supports):
                raise TypeError(f"not an order: {o!r}")
            r.pending.append((r.k + self.latency, o))

    def trace(self, i: int) -> Trace:
        r = self.rows[i]
        return Trace.build(r.ep, r.mids, r.log.now[3:], r.fills, r.decisions, r.signals, r.refused,
                           {k: int(v) for k, v in r.gen.items()})

    # ------------------------------------------------------------ one background message per row
    @torch.no_grad()
    def advance(self) -> None:
        for r in self.rows:
            if r.k >= self.n_messages:
                r.bg_done = True
                continue
            self._activate(r)
            r.bg_done = False
            self._next_message(r)
        while True:
            active = [not r.bg_done for r in self.rows] + [False] * (self.batch - len(self.rows))
            if not any(active):
                break
            tok = torch.tensor([r.inp for r in self.rows] + [START] * (self.batch - len(self.rows)), device=self.dev)
            bv = np.stack([r.bvec for r in self.rows] + [self.rows[0].bvec] * (self.batch - len(self.rows)))
            logits = self.sim.step(tok, torch.as_tensor(bv, device=self.dev), active).double().cpu().numpy()
            for i, r in enumerate(self.rows):
                if active[i]:
                    self._on_logits(i, r, logits[i])
        for r in self.rows:
            if r.k < self.n_messages:
                r.k += 1
                r.mids.append(mid_of(r.log.now[3:]))

    def _next_message(self, r: _Row) -> None:
        """Start the next message of a row: a waiting agent message, else a background draw."""
        if r.agent:
            r.forced, r.after = r.agent.pop(0)
            r.state = None
            return
        r.forced, r.after = [], None
        r.attempt = 0
        r.rng = np.random.default_rng([r.ep.seed, r.k, 0])
        r.state = MessageState(self._t_prev(r))

    def _on_logits(self, i: int, r: _Row, logits: np.ndarray) -> None:
        if r.forced:                                   # an agent message: logits are not used
            r.inp = r.forced.pop(0)
            if not r.forced:
                r.bvec = r.after
                self._next_message(r)
            return
        st = r.state
        if not st.toks:
            r.logits0, r.n_start = logits, self.sim.n[i]
        tok = self._draw(r, logits)
        st.push(tok)
        while st.done():
            m, reason = finish(st, r.book, self._mid(r), r.end)
            if m is not None:
                self._apply_background(r, m)
                r.inp, r.bvec, r.bg_done = tok, self._bvec(r), True
                return
            r.gen["rejected_" + reason] += 1
            r.gen["first_rejected"] += int(r.attempt == 0)
            r.attempt += 1
            r.gen["fallback"] += int(r.attempt == self.max_rejections)
            r.rng = np.random.default_rng([r.ep.seed, r.k, r.attempt])
            self.sim.truncate(i, r.n_start)
            st = r.state = MessageState(st.t_prev)
            tok = self._draw(r, r.logits0)
            st.push(tok)
        r.inp = tok

    def _draw(self, r: _Row, logits: np.ndarray) -> int:
        st = r.state
        f = st.forced()
        if f is not None:
            return f
        p = np.exp(logits - logits.max())
        if r.attempt >= self.max_rejections:
            ok = legal_tokens(st, r.book, self._mid(r), r.end)
            if not len(ok):
                raise RuntimeError(f"no legal token after {st.toks} in {r.ep.entry['message']} k={r.k}")
            q = np.zeros_like(p)
            q[ok] = p[ok]
            p = q if q.sum() > 0 else np.isin(np.arange(len(p)), ok).astype(np.float64)
        return int(r.rng.choice(len(p), p=p / p.sum()))

    # ------------------------------------------------------------ state changes
    def _t_prev(self, r: _Row) -> int:
        t = r.log.rows(1)[0]
        return int(t[8]) * NS + int(t[9])

    def _mid(self, r: _Row) -> int:
        """The newtok reference price, from the L10 row as the training data has it
        (an empty side carries its placeholder price)."""
        return mid_floor(r.log.now[3], r.log.now[5])

    def _bvec(self, r: _Row) -> np.ndarray:
        return book_features(r.log.now[None])[0]

    def _row(self, r: _Row, oid, evt, d, price, size, dt, t) -> None:
        row = processed_row(oid, evt, d, price, size, dt // NS, dt % NS, t // NS, t % NS, r.log.now, r.reg, r.clip)
        r.reg.observe(row)
        r.log.append(row, r.writer.next_row(r.book, t // NS, t % NS))

    def _apply_background(self, r: _Row, m: Message) -> None:
        side, (price, size) = side_of_direction(m.d), m.levels[0]
        r.gen["messages"] += 1
        if m.evt == 1:
            oid, r.next_bg = r.next_bg, r.next_bg + 1
            r.book.add(side, price, oid, size)
            self._row(r, oid, 1, m.d, price, size, m.dt, m.time)
        elif m.evt in (2, 3):
            slots = slot_candidates(m, r.book)
            slot = slots[0] if m.qslot < LAST_SLOT else slots[int(r.rng.integers(len(slots)))]
            o = r.book.queue(side, price)[slot]
            oid, rem = o.oid, o.size
            if m.evt == 3:
                r.book.remove_at(side, price, slot)
            else:
                r.book.reduce_at(side, price, slot, size)
            self._row(r, oid, m.evt, m.d, price, rem if m.evt == 3 else size, m.dt, m.time)
        else:
            mid = mid_of(r.log.now[3:])
            first = True
            for price, size in m.levels:
                left = min(size, r.book.volume(side, price))
                while left > 0:
                    o = r.book.queue(side, price)[0]
                    take = min(left, o.size)
                    if o.owner == AGENT:
                        self._agent_fill(r, Fill(r.k, BUY if side == BID else -BUY, float(price), take, True, mid))
                    r.book.reduce_at(side, price, 0, take)
                    if o.owner == AGENT and not r.book.has(o.oid):
                        r.resting.pop(o.oid, None)
                    self._row(r, o.oid, 4, m.d, price, take, m.dt if first else 0, m.time)
                    first, left = False, left - take

    def _agent_fill(self, r: _Row, f: Fill) -> None:
        r.position += f.side * f.size
        r.cash -= f.side * f.size * f.price
        r.fills.append(f)
        r.new.append(f)

    def _activate(self, r: _Row) -> None:
        due = [o for at, o in r.pending if at <= r.k]
        r.pending = [(at, o) for at, o in r.pending if at > r.k]
        for o in due:
            msg = self._agent_message(r, o)
            if msg is None:
                r.refused += 1
                continue
            r.gen["agent_messages"] += 1

    def _exposure(self, r: _Row, side: int) -> int:
        """Position if every resting agent order on `side` (BUY or SELL) filled."""
        rest = sum(o.size for p in r.book.prices(BID if side == BUY else ASK)
                   for o in r.book.queue(BID if side == BUY else ASK, p) if o.owner == AGENT)
        return r.position + side * rest

    def _agent_message(self, r: _Row, o):
        """Apply an agent order to the book and queue its message. None if refused."""
        mid = self._mid(r)
        t = self._t_prev(r) + 1                        # 1 ns after the previous message
        if isinstance(o, Cancel):
            if o.oid not in r.resting or not r.book.has(o.oid):
                return None
            side, price = r.book.location(o.oid)
            if len(r.book.prices(side)) == 1 and len(r.book.queue(side, price)) == 1:
                return None
            slot = r.book.slot_of(o.oid)
            rem = r.book.queue(side, price)[slot].size
            m = Message(3, 1 if side == BID else 0, 0, 1, t // NS, t % NS, ((price, min(rem, MAX_SIZE)),),
                        min(slot, LAST_SLOT))
            toks = encode(m, mid)
            r.book.remove_at(side, price, slot)
            r.resting.pop(o.oid)
            self._row(r, o.oid, 3, m.d, price, rem, 1, t)
        elif isinstance(o, LimitOrder):
            side = BID if o.side == BUY else ASK
            opp = r.book.best(-side)
            crosses = opp is not None and (o.price >= opp if side == BID else o.price <= opp)
            if o.price % TICK or o.price <= 0 or crosses \
                    or abs(self._exposure(r, o.side) + o.side * o.size) > self.cap:
                return None
            oid, r.next_agent = r.next_agent, r.next_agent + 1
            m = Message(1, 1 if side == BID else 0, 0, 1, t // NS, t % NS, ((o.price, o.size),))
            toks = encode(m, mid)
            r.book.add(side, o.price, oid, o.size, AGENT)
            r.resting[oid] = o.side
            self._row(r, oid, 1, m.d, o.price, o.size, 1, t)
        else:
            side = ASK if o.side == BUY else BID          # the side the order takes from
            if abs(r.position + o.side * o.size) > self.cap or side_volume(r.book, side) <= o.size:
                return None
            d, levels, left = 1 if side == BID else 0, [], o.size
            for p in r.book.prices(side):
                take = min(left, r.book.volume(side, p))
                levels.append((p, take))
                left -= take
                if left == 0:
                    break
            m = Message(4, d, 0, 1, t // NS, t % NS, tuple(levels))
            toks = encode(m, mid)
            mid_now, first = mid_of(r.log.now[3:]), True
            for p, q in levels:
                while q > 0:
                    rest = r.book.queue(side, p)[0]
                    take = min(q, rest.size)
                    own = rest.owner == AGENT          # its own resting order: the maker side too
                    if own:
                        self._agent_fill(r, Fill(r.k, -o.side, float(p), take, True, mid_now))
                    r.book.reduce_at(side, p, 0, take)
                    if own and not r.book.has(rest.oid):
                        r.resting.pop(rest.oid, None)
                    self._row(r, rest.oid, 4, d, p, take, 1 if first else 0, t)
                    self._agent_fill(r, Fill(r.k, o.side, float(p), take, False, mid_now))
                    first, q = False, q - take
        r.agent.append((list(toks), self._bvec(r)))
        return m
